from PyQt5.QtCore import QUrl
for raw in ['http://localhost/%3A5?q=%253A10#%3A20', 'http://host_5.example/path%2F6?x=%3A7#%3A8']:
    u = QUrl(raw)
    print('URL', bytes(u.toEncoded()).decode())
    for name, getter in [('host', u.host), ('path', u.path), ('query', u.query), ('fragment', u.fragment)]:
        try:
            print(name, repr(getter(QUrl.FullyEncoded)), repr(getter()))
        except Exception as e:
            print(name, type(e).__name__, e)
    for setter_name in ['setHost', 'setPath', 'setQuery', 'setFragment']:
        print(setter_name, getattr(QUrl, setter_name).__doc__)
