from PyQt5.QtCore import QUrl
for mode in [QUrl.DecodedMode, QUrl.TolerantMode, QUrl.StrictMode]:
  for meth, value in [('setPath','/%3A5'), ('setQuery','x=%3A5'), ('setFragment','%3A5'), ('setHost','a%3A5.example')]:
    u=QUrl('http://example.com/base?z=8#end')
    try:
      getattr(u,meth)(value, mode)
      print(mode, meth, bytes(u.toEncoded()).decode(), 'valid=',u.isValid())
    except Exception as e: print(mode,meth,type(e).__name__,e)
