/bin/bash -lc "python - <<'PY'
from PyQt5.QtCore import QUrl
from qutebrowser.utils.urlutils import incdec_number, IncDecError
cases = [
    ('http://localhost/%3A5', {'path'}),
    ('http://localhost/%3A10?q=%3A11#%3A12', {'query'}),
    ('http://localhost/%253A10', {'path'}),
    ('http://host_9.example/path_8?x=7#n6', {'path', 'query', 'anchor', 'host'}),
    ('http://host_9.example/path_8?x=7#n6', {'host'}),
]
for raw, segments in cases:
    u=QUrl(raw)
    try:
        out=incdec_number(u, 'increment', segments=segments)
        print(raw, '=>', bytes(out.toEncoded()).decode())
    except Exception as e:
        print(raw, type(e).__name__, str(e))
for raw, count in [('http://example.com/page_1.html', 2), ('http://example.com/page_0.html', 1)]:
    try: print(incdec_number(QUrl(raw), 'decrement', count))
    except Exception as e: print(type(e).__name__, str(e))
PY"

